-- Spec 005 Shift calendar and availability (specs/005-shifts/data-model.md › Migration). Generated by
-- `prisma migrate diff` (the columns), then completed by hand: one CHECK and one partial unique index,
-- which Prisma can't express. No policy changes: shifts_student, patterns_student (own rows) and
-- shifts_admin_read, patterns_admin_read (linked Admin, read only) already match FR-008. Nothing
-- SQL-only is dropped.

-- AlterTable: preset times per student (FR-002, research R3) and the Sunday check (FR-009, R9).
ALTER TABLE "profiles" ADD COLUMN     "shift_presets" JSONB NOT NULL DEFAULT '{"D": ["09:00", "18:00"], "E": ["14:00", "23:00"], "N": ["22:00", "07:00"]}',
ADD COLUMN     "shifts_confirmed_week" DATE;

-- AlterTable: presets move to the profile (R3); generated_until drives the daily top-up (R4).
-- shift_patterns was empty on dev when this was written (tasks.md T001), so nothing is lost.
ALTER TABLE "shift_patterns" DROP COLUMN "presets",
ADD COLUMN     "generated_until" DATE;

-- An Off day is free time with no sleep block (research R2): busy_segments() adds sleep after any
-- row with sleep_minutes > 0. No Off row had sleep on dev (tasks.md T001).
alter table public.shifts
  add constraint shifts_off_no_sleep check (type <> 'off' or sleep_minutes = 0);

-- One active rotation per student (FR-010); saving a new one deactivates the old one first.
create unique index shift_patterns_one_active on public.shift_patterns (student_id) where active;
